/// Searches for `k` in a non-empty sorted (non-decreasing) array `v`.
/// Preconditions (as stated in the problem):
/// - `v` is non-empty
/// - `v` is sorted in non-decreasing order
/// - `k` occurs at least once in `v`
///
/// Returns an index `r` such that `r < v.len()` and `v[r] == k`.
pub fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut lo: usize = 0;
    let mut hi: usize = v.len() - 1; // inclusive upper bound; valid since v is non-empty

    // Invariants maintained throughout the loop:
    // - 0 <= lo <= hi < v.len()  (active interval stays within bounds)
    // - k occurs in v[lo..=hi]   (at least one occurrence remains in the interval)
    //
    // Progress/termination:
    // - Each iteration strictly decreases interval size (hi - lo decreases),
    //   because we either set lo = mid + 1 or hi = mid.
    while lo < hi {
        let mid = lo + (hi - lo) / 2;

        // Since k is guaranteed to exist somewhere in v[lo..=hi]:
        // - If v[mid] < k, then k cannot be in [lo..=mid], so move lo up.
        // - Otherwise (v[mid] >= k), there is still a k in [lo..=mid] or at least
        //   in [lo..=hi] with the left part still viable, so shrink hi to mid.
        if v[mid] < k {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    // Now lo == hi, interval has size 1, and invariant says k is in v[lo..=hi].
    // So v[lo] must equal k.
    debug_assert!(lo < v.len());
    debug_assert!(v[lo] == k);
    lo
}

